var o=`0597-khorkhog`;var i=`world-0597`;var n=`MN`;var a=`east-asia`;var s=4;var r=179;var l={en:`Khorkhog`,ua:`Хорхог`};var g={en:`A traditional dish from Mongolia, centered on lamb, yellow onion, garlic, potato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Монголія. Основні складники: ягнятина, жовта цибуля, часник, картопля. Домашній варіант із кількостями продуктів за етапами приготування.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 75 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 75 хвилин.`,t:[`marinating`],m:75,i:[[`lamb`,900,`g`],[`yellow-onion`,230,`g`],[`garlic`,4,`clove`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Slow-roast lamb with the vegetables tightly covered. Traditional khorkhog uses hot stones inside a sealed vessel; this oven method deliberately does not.`,ua:`Повільно запікайте баранину з овочами під щільною кришкою. Традиційний хорхог готують із гарячим камінням у закритій посудині; тут використано безпечніший метод у духовці.`,t:[`roasting`],m:100,i:[[`potato`,580,`g`],[`carrot`,430,`g`],[`water`,300,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,25,`g`]]}];var d={slug:o,id:i,country:`MN`,region:a,servings:4,minutes:179,title:l,text:g,steps:h};export{n as country,d as default,i as id,r as minutes,a as region,s as servings,o as slug,h as steps,g as text,l as title};